function mergeHeaders(...headerSources) {
    const merged = {};
    for (const headers of headerSources) {
        if (!headers)
            continue;
        for (const [key, value] of Object.entries(headers)) {
            // Append+dedupe anthropic-beta instead of overwriting, so callers can add
            // betas (e.g. fast-mode) without clobbering oauth/interleaved-thinking.
            if (key.toLowerCase() === "anthropic-beta" && merged[key] && value) {
                const betas = new Set(String(merged[key]).split(",").map((s) => s.trim()).filter(Boolean));
                for (const b of String(value).split(",").map((s) => s.trim()).filter(Boolean))
                    betas.add(b);
                merged[key] = [...betas].join(",");
            }
            else {
                merged[key] = value;
            }
        }
    }
    return merged;
}
